//! Z80 LLIL lifter ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â mnemonic-driven, covers the full Z80 ISA.
//!
//! The Zilog Z80 is an 8-bit processor with a rich instruction set inherited
//! from the Intel 8080, extended with:
//!   - 16-bit register pairs (BC, DE, HL, SP, AF)
//!   - Index registers IX and IY with 8-bit displacement
//!   - Shadow registers AF'/BC'/DE'/HL' (exchanged via EXX/EX AF,AF')
//!   - Bit manipulation (CB prefix), extended ops (ED prefix)
//!   - Block copy / compare / I/O instructions
//!
//! Register names used in IR (lower-case, no prefix):
//!   8-bit : a, b, c, d, e, h, l, f, i, r
//!   16-bit: bc, de, hl, sp, pc, af, ix, iy
//!   shadow: `af_shadow`, `bc_shadow`, `de_shadow`, `hl_shadow`
//!   flags : cf (carry), nf (add/sub), pf (parity/overflow), hf (half-carry),
//!           zf (zero), sf (sign)
//!
//! Operand parsing notes:
//!   - Disassemblers typically emit operands as Register, Immediate, or Memory.
//!   - Memory operands with a base register model `(HL)`, `(BC)`, `(DE)`,
//!     `(SP)` and index-register forms `(IX+d)` / `(IY+d)`.
//!   - Immediate operands carry 8-bit or 16-bit literal values.
//!   - Labels carry resolved absolute addresses for JP/CALL targets.

use super::{ArchLifter, Effect, IrExpr, LiftError, LiftLevel, LiftedInstr};
use rustre_core::arch::{Instruction, Operand};
use std::fmt;

// ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
// Z80Lifter
// ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

/// LLIL lifter for the Zilog Z80 (and Z80-compatible) instruction set.
///
/// Produces [`LiftLevel::Llil`] IR.  Most instructions are modelled with precise
/// data-flow effects; a small number of rarely-used or complex instructions fall
/// back to an [`Effect::Intrinsic`] stub.
///
/// # Examples
///
/// ```
/// use rustre_il_lift::z80_lifter::Z80Lifter;
///
/// let nmos = Z80Lifter::new();
/// let cmos = Z80Lifter::new_cmos();
/// let z180 = Z80Lifter::new_z180();
/// ```
///
/// The example was `ignore`d until 2026-07-29 and read
/// `lifter.lift(&instr)?` — **there is no `lift` method on this type**;
/// its public surface is the three constructors above. The documentation
/// advertised an API that has never existed.
#[derive(Debug, Clone)]
pub struct Z80Lifter {
    /// Marker so the struct is not zero-sized; reserved for future options
    /// (e.g. undocumented opcode support, CMOS vs NMOS variant flags).
    variant: Z80Variant,
}

/// Z80 silicon variant ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â reserved for future use.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Z80Variant {
    /// Standard Zilog Z80 (NMOS).
    Standard,
    /// Z80 CMOS (minor flag differences on a few instructions).
    Cmos,
    /// Z180 / HD64180 (adds some extra instructions, used for optional coverage).
    Z180,
}

impl Z80Lifter {
    /// Create a lifter for the standard Zilog Z80.
    #[must_use]
    pub const fn new() -> Self {
        Self {
            variant: Z80Variant::Standard,
        }
    }

    /// Create a lifter for the Z80 CMOS variant.
    #[must_use]
    pub const fn new_cmos() -> Self {
        Self {
            variant: Z80Variant::Cmos,
        }
    }

    /// Create a lifter for the Z180 (HD64180) variant.
    #[must_use]
    pub const fn new_z180() -> Self {
        Self {
            variant: Z80Variant::Z180,
        }
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Operand helpers ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    /// Convert a structured [`Operand`] to an [`IrExpr`].
    ///
    /// Register operands become [`IrExpr::Reg`] with lower-cased names.
    /// Immediate and Label operands become [`IrExpr::Const`].
    /// Memory operands produce the *effective address* expression ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â callers
    /// wrap it in [`IrExpr::Deref`] when a load is required.
    fn operand_to_expr(op: &Operand) -> IrExpr {
        match op {
            Operand::Register(r) => IrExpr::Reg(r.name.to_ascii_lowercase()),
            Operand::Immediate(v) => IrExpr::Const((*v).cast_unsigned()),
            Operand::UImmediate(v) => IrExpr::Const(*v),
            Operand::Label(addr) => IrExpr::Const(*addr),
            Operand::Memory {
                base,
                index: _,
                scale: _,
                disp,
                ..
            } => {
                // Z80 memory: base register (HL, BC, DE, SP, IX, IY) + optional disp.
                let base_expr = base
                    .as_ref()
                    .map_or(IrExpr::Const(0), |r| IrExpr::Reg(r.name.to_ascii_lowercase()));
                if *disp != 0 {
                    let d = IrExpr::Const((*disp).unsigned_abs());
                    if *disp < 0 {
                        IrExpr::Sub(Box::new(base_expr), Box::new(d))
                    } else {
                        IrExpr::Add(Box::new(base_expr), Box::new(d))
                    }
                } else {
                    base_expr
                }
            }
            Operand::FpReg(n) => IrExpr::Reg(format!("fp{n}")),
            Operand::VecReg(n) => IrExpr::Reg(format!("v{n}")),
            Operand::Segment(_, inner) => Self::operand_to_expr(inner),
        }
    }

    /// Return operand `i` as an [`IrExpr`], or [`IrExpr::Undef`] when absent.
    fn op_expr(instr: &Instruction, i: usize) -> IrExpr {
        instr
            .operand_list
            .get(i)
            .map_or(IrExpr::Undef, Self::operand_to_expr)
    }

    /// Return the register name of operand `i`, or a fallback string.
    fn op_reg(instr: &Instruction, i: usize) -> Option<String> {
        instr.operand_list.get(i).and_then(|op| {
            if let Operand::Register(r) = op {
                Some(r.name.to_ascii_lowercase())
            } else {
                None
            }
        })
    }

    /// Return the register name of operand `i`, falling back to `fallback`.
    fn op_reg_or(instr: &Instruction, i: usize, fallback: &str) -> String {
        Self::op_reg(instr, i).unwrap_or_else(|| fallback.to_string())
    }

    /// Return the resolved branch/call target from the first operand.
    ///
    /// Priority: Label ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ absolute address; Immediate ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ interpreted as absolute
    /// address when >= 0x100 (Z80 code space), otherwise treated as relative to
    /// the next instruction (for JR); Register ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ indirect (Reg expression).
    fn branch_target(instr: &Instruction) -> IrExpr {
        let next_pc = instr.address.0.wrapping_add(instr.size as u64);
        match instr.operand_list.first() {
            Some(Operand::Label(addr)) => IrExpr::Const(*addr),
            Some(Operand::Immediate(v)) => {
                // JR encodes a signed PC-relative offset in a single byte.
                // Absolute CALL/JP targets are always >= 0x100 for real programs.
                if *v >= 0x100 {
                    IrExpr::Const((*v).cast_unsigned())
                } else {
                    // Treat as signed relative offset from next instruction.
                    let off = *v;
                    IrExpr::Const(next_pc.wrapping_add(off.cast_unsigned()))
                }
            }
            Some(Operand::UImmediate(v)) => IrExpr::Const(*v),
            Some(Operand::Register(r)) => IrExpr::Reg(r.name.to_ascii_lowercase()),
            Some(Operand::Memory { base, disp, .. }) => {
                // JP (HL) / JP (IX) / JP (IY)
                let base_expr = base
                    .as_ref()
                    .map_or(IrExpr::Const(0), |r| IrExpr::Reg(r.name.to_ascii_lowercase()));
                if *disp != 0 {
                    let d = IrExpr::Const((*disp).unsigned_abs());
                    if *disp < 0 {
                        IrExpr::Sub(Box::new(base_expr), Box::new(d))
                    } else {
                        IrExpr::Add(Box::new(base_expr), Box::new(d))
                    }
                } else {
                    base_expr
                }
            }
            _ => IrExpr::Const(next_pc),
        }
    }

    /// Resolve a conditional branch target, skipping the condition operand (op 1)
    /// and reading the address from operand 0 for JP cc,nn / CALL cc,nn.
    ///
    /// For these the condition string is operand 0 (a special Register operand
    /// named `"z"`, `"nz"`, `"c"`, `"nc"`, `"pe"`, `"po"`, `"p"`, `"m"`) and
    /// the address is operand 1.
    fn cond_branch_target(instr: &Instruction) -> IrExpr {
        // Try operand 1 first (condition in op0, address in op1).
        if instr.operand_list.len() >= 2 {
            match &instr.operand_list[1] {
                Operand::Label(addr) => return IrExpr::Const(*addr),
                Operand::Immediate(v) => return IrExpr::Const((*v).cast_unsigned()),
                Operand::UImmediate(v) => return IrExpr::Const(*v),
                _ => {}
            }
        }
        // Fall back to op0 for unconditional forms re-used here.
        Self::branch_target(instr)
    }

    /// Map a Z80 condition-code string to an [`IrExpr`] over the flag registers.
    ///
    /// Returns `None` for conditions encoded on registers that aren't present
    /// in the operand list (shouldn't happen for well-formed disassembly).
    fn condition_expr(cond: &str) -> Option<IrExpr> {
        match cond.to_ascii_lowercase().as_str() {
            // NZ ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â jump if Z flag = 0
            "nz" => Some(IrExpr::CmpEqZero(Box::new(IrExpr::Reg("zf".to_string())))),
            // Z ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â jump if Z flag = 1
            "z" => Some(IrExpr::Not(Box::new(IrExpr::CmpEqZero(Box::new(
                IrExpr::Reg("zf".to_string()),
            ))))),
            // NC ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â jump if C flag = 0
            "nc" => Some(IrExpr::CmpEqZero(Box::new(IrExpr::Reg("cf".to_string())))),
            // C ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â jump if C flag = 1
            "c" => Some(IrExpr::Not(Box::new(IrExpr::CmpEqZero(Box::new(
                IrExpr::Reg("cf".to_string()),
            ))))),
            // PO ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â parity odd (P/V = 0)
            "po" => Some(IrExpr::CmpEqZero(Box::new(IrExpr::Reg("pf".to_string())))),
            // PE ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â parity even (P/V = 1)
            "pe" => Some(IrExpr::Not(Box::new(IrExpr::CmpEqZero(Box::new(
                IrExpr::Reg("pf".to_string()),
            ))))),
            // P ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â sign positive (S = 0)
            "p" => Some(IrExpr::CmpEqZero(Box::new(IrExpr::Reg("sf".to_string())))),
            // M ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â sign minus (S = 1)
            "m" => Some(IrExpr::Not(Box::new(IrExpr::CmpEqZero(Box::new(
                IrExpr::Reg("sf".to_string()),
            ))))),
            _ => None,
        }
    }

    /// Build a Z80 conditional-branch condition from operand 0 (the condition
    /// register name such as `"nz"`, `"z"`, `"nc"`, etc.).
    fn cond_from_op0(instr: &Instruction) -> Option<IrExpr> {
        let cond_name = Self::op_reg(instr, 0)?;
        Self::condition_expr(&cond_name)
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ SP / push / pop helpers ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    /// SP decrement + store (PUSH rr): SP -= 2; [SP] = high; [SP+1] = low.
    /// We model it as a single 16-bit memory write to SP-2 for simplicity.
    fn push_effects(rr: &str) -> Vec<Effect> {
        let sp = IrExpr::Reg("sp".to_string());
        let new_sp = IrExpr::Sub(Box::new(sp), Box::new(IrExpr::Const(2)));
        vec![
            // SP = SP - 2
            Effect::RegWrite {
                reg: "sp".to_string(),
                value: new_sp.clone(),
            },
            // [SP] = rr (16-bit)
            Effect::MemWrite {
                addr: new_sp,
                value: IrExpr::Reg(rr.to_ascii_lowercase()),
                size: 2,
            },
        ]
    }

    /// SP load + increment (POP rr): rr = [SP]; SP += 2.
    fn pop_effects(rr: &str) -> Vec<Effect> {
        let sp = IrExpr::Reg("sp".to_string());
        vec![
            // rr = [SP]
            Effect::MemRead {
                addr: sp.clone(),
                dest: rr.to_ascii_lowercase(),
                size: 2,
            },
            // SP = SP + 2
            Effect::RegWrite {
                reg: "sp".to_string(),
                value: IrExpr::Add(Box::new(sp), Box::new(IrExpr::Const(2))),
            },
        ]
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Main dispatch ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    /// Translate a single Z80 mnemonic + operand list into a list of [`Effect`]s.
    fn mnemonic_to_effects_a(instr: &Instruction) -> Option<Vec<Effect>> {
        let mnem = instr.mnemonic.to_ascii_lowercase();
        // Strip any trailing whitespace the disassembler might emit.
        let mnem = mnem.trim();

            Some(match mnem {
            // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ NOP / HALT ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

            "nop" => vec![],

            "halt" => vec![Effect::Intrinsic {
                name: "halt".to_string(),
                args: vec![],
            }],

            // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ LD ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â register to register ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
            // LD r, r  /  LD r, n  /  LD r, (HL)  /  LD (HL), r  /  LD (HL), n
            // LD rr, nn  /  LD (nn), A  /  LD A, (nn)  /  LD SP, HL  etc.
            "ld" => Self::lift_ld(instr),

            // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ LD I/R variants (these are separate mnemonics on many disassemblers) ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
            "ld_i_a" | "ld i,a" => vec![Effect::RegWrite {
                reg: "i".to_string(),
                value: IrExpr::Reg("a".to_string()),
            }],
            "ld_r_a" | "ld r,a" => vec![Effect::RegWrite {
                reg: "r".to_string(),
                value: IrExpr::Reg("a".to_string()),
            }],
            "ld_a_i" | "ld a,i" => vec![Effect::RegWrite {
                reg: "a".to_string(),
                value: IrExpr::Reg("i".to_string()),
            }],
            "ld_a_r" | "ld a,r" => vec![Effect::RegWrite {
                reg: "a".to_string(),
                value: IrExpr::Reg("r".to_string()),
            }],

            // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ PUSH / POP ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
            "push" => {
                let rr = Self::op_reg_or(instr, 0, "af");
                Self::push_effects(&rr)
            }
            "pop" => {
                let rr = Self::op_reg_or(instr, 0, "af");
                Self::pop_effects(&rr)
            }

            // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ 8-bit Arithmetic ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
            // ADD A, r/n/(HL)/(IX+d) ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â A = A + src
            "add" => Self::lift_add(instr),

            // ADC A, r/n/(HL) ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â A = A + src + CF
            "adc" => Self::lift_adc(instr),

            // SUB r/n/(HL) ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â A = A - src  (single-operand on Z80)
            "sub" => Self::lift_sub(instr),

            // SBC A, r/n/(HL) ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â A = A - src - CF
            "sbc" => Self::lift_sbc(instr),

            // INC r / INC rr / INC (HL)
            "inc" => Self::lift_inc(instr),

            // DEC r / DEC rr / DEC (HL)
            "dec" => Self::lift_dec(instr),

            // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ 8-bit Logic ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
            "and" => Self::lift_bitop(instr, IrExpr::And),
            "or" => Self::lift_bitop(instr, IrExpr::Or),
            "xor" => Self::lift_bitop(instr, IrExpr::Xor),

            // CP r/n ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â compare A with src (sets flags, no write)
            "cp" => {
                let src = if instr.operand_list.len() == 1 {
                    Self::op_expr(instr, 0)
                } else {
                    Self::op_expr(instr, 1)
                };
                vec![Effect::Intrinsic {
                    name: "cp".to_string(),
                    args: vec![IrExpr::Reg("a".to_string()), src],
                }]
            }

            // CPL ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â complement A (bitwise NOT, sets H and N flags)
            "cpl" => vec![Effect::RegWrite {
                reg: "a".to_string(),
                value: IrExpr::Not(Box::new(IrExpr::Reg("a".to_string()))),
            }],

            // NEG ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â negate A (two's complement: A = 0 - A)
            "neg" => vec![Effect::RegWrite {
                reg: "a".to_string(),
                value: IrExpr::Sub(
                    Box::new(IrExpr::Const(0)),
                    Box::new(IrExpr::Reg("a".to_string())),
                ),
            }],

            // DAA ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â decimal adjust accumulator
            "daa" => Self::accumulator_op("daa", None),
                _ => return None,
            })
    }
    fn mnemonic_to_effects_b_a(instr: &Instruction) -> Option<Vec<Effect>> {
        let mnem = instr.mnemonic.to_ascii_lowercase();
        // Strip any trailing whitespace the disassembler might emit.
        let mnem = mnem.trim();

                Some(match mnem {
            "scf" => vec![Effect::Intrinsic {
                name: "scf".to_string(),
                args: vec![],
            }],
            "ccf" => vec![Effect::Intrinsic {
                name: "ccf".to_string(),
                args: vec![],
            }],
            "rlca" => Self::accumulator_op("rlca", Some(true)),
            "rla" => Self::accumulator_op("rla", None),
            "rrca" => Self::accumulator_op("rrca", Some(false)),
            "rra" => Self::accumulator_op("rra", None),
            "rlc" | "rrc" | "rl" | "rr" | "sla" | "sra" | "srl" => {
                Self::lift_shift_rotate(instr, mnem)
            }
            "bit" => {
                // BIT b, r ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â test bit, sets Z flag; no register write
                let bit_n = Self::op_expr(instr, 0);
                let src = Self::op_expr(instr, 1);
                vec![Effect::Intrinsic {
                    name: "bit".to_string(),
                    args: vec![bit_n, src],
                }]
            }
            "set" => {
                // SET b, r ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â set bit b in r
                let bit_n = Self::op_expr(instr, 0);
                let dst = Self::op_reg_or(instr, 1, "a");
                let src = IrExpr::Reg(dst.clone());
                let mask = IrExpr::Shl(Box::new(IrExpr::Const(1)), Box::new(bit_n));
                vec![Effect::RegWrite {
                    reg: dst,
                    value: IrExpr::Or(Box::new(src), Box::new(mask)),
                }]
            }
            "res" => {
                // RES b, r ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â reset bit b in r
                let bit_n = Self::op_expr(instr, 0);
                let dst = Self::op_reg_or(instr, 1, "a");
                let src = IrExpr::Reg(dst.clone());
                // mask = ~(1 << b)
                let mask = IrExpr::Not(Box::new(IrExpr::Shl(
                    Box::new(IrExpr::Const(1)),
                    Box::new(bit_n),
                )));
                vec![Effect::RegWrite {
                    reg: dst,
                    value: IrExpr::And(Box::new(src), Box::new(mask)),
                }]
            }
            "jp" => Self::lift_jp(instr),
            "jr" => Self::lift_jr(instr),
                    _ => return None,
                })
    }

    fn mnemonic_to_effects_b_b(instr: &Instruction) -> Option<Vec<Effect>> {
        let mnem = instr.mnemonic.to_ascii_lowercase();
        // Strip any trailing whitespace the disassembler might emit.
        let mnem = mnem.trim();

                Some(match mnem {
            "djnz" => {
                let target = Self::branch_target(instr);
                let new_b = IrExpr::Sub(
                    Box::new(IrExpr::Reg("b".to_string())),
                    Box::new(IrExpr::Const(1)),
                );
                vec![
                    // B = B - 1
                    Effect::RegWrite {
                        reg: "b".to_string(),
                        value: new_b,
                    },
                    // if B != 0 goto target  (CmpEqZero returns 1 when B==0,
                    // so we negate to get "branch taken when B != 0")
                    Effect::Branch {
                        target,
                        condition: Some(IrExpr::Not(Box::new(IrExpr::CmpEqZero(Box::new(
                            IrExpr::Reg("b".to_string()),
                        ))))),
                    },
                ]
            }
            "call" => Self::lift_call(instr),
            "ret" => Self::lift_ret(instr),
            "reti" => vec![
                Effect::Intrinsic {
                    name: "reti".to_string(),
                    args: vec![],
                },
                Effect::Return { value: None },
            ],
            "retn" => vec![
                Effect::Intrinsic {
                    name: "retn".to_string(),
                    args: vec![],
                },
                Effect::Return { value: None },
            ],

            // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ RST ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â restart (call to fixed address 0,8,16,...,56) ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
            "rst" => {
                let target = Self::op_expr(instr, 0);
                // Inline push of PC, then jump.
                let sp = IrExpr::Reg("sp".to_string());
                let new_sp = IrExpr::Sub(Box::new(sp), Box::new(IrExpr::Const(2)));
                let next_pc = instr.address.0.wrapping_add(instr.size as u64);
                vec![
                    Effect::RegWrite {
                        reg: "sp".to_string(),
                        value: new_sp.clone(),
                    },
                    Effect::MemWrite {
                        addr: new_sp,
                        value: IrExpr::Const(next_pc),
                        size: 2,
                    },
                    Effect::Call { target },
                ]
            }
            "ex" => Self::lift_ex(instr),
            // EXX swaps BC/DE/HL with the shadow bank. A swap needs temporaries
            // in a sequentially-applied effect list, and inventing fixed temp
            // names is the collision trap seen elsewhere in this crate — so the
            // CLOBBERS are declared instead of the exchange being modelled.
            // That still removes the false claim that EXX changes nothing.
            "exx" => {
                let mut e = vec![Effect::Intrinsic {
                    name: "exx".to_string(),
                    args: vec![
                        IrExpr::Reg("bc".to_string()),
                        IrExpr::Reg("de".to_string()),
                        IrExpr::Reg("hl".to_string()),
                    ],
                }];
                for r in ["bc", "de", "hl", "bc_shadow", "de_shadow", "hl_shadow"] {
                    e.push(Effect::RegWrite {
                        reg: r.to_string(),
                        value: IrExpr::Undef,
                    });
                }
                e
            }
            "ldi" => Self::block_transfer("ldi", true, false),
            "ldir" => Self::block_transfer("ldir", true, true),
                _ => return None,
                })
    }

    /// Register effects of the Z80 BLOCK instructions.
    ///
    /// These take no operands in the assembly syntax, and every one of them
    /// used to lift to a bare `Effect::Intrinsic` with `args: vec![]` and no
    /// register writes at all. That is not opacity — it is the CLAIM that
    /// `LDIR` leaves HL, DE and BC untouched, which a liveness or dead-store
    /// pass will believe. Same class as the arch-x86 register-effect sweep,
    /// where "never wrote registers the decoder reports" was the defect.
    ///
    /// `LDI`/`LDD` are exact: one byte moves and the three pairs step by one.
    /// The repeating forms end with `BC = 0` and the pointers advanced by the
    /// ORIGINAL count, which is also exact; the block copy itself stays an
    /// intrinsic because a loop is not expressible in an effect list.
    fn block_transfer(name: &str, step_up: bool, repeat: bool) -> Vec<Effect> {
        let reg = |r: &str| IrExpr::Reg(r.to_string());
        let mut effects = vec![Effect::Intrinsic {
            name: name.to_string(),
            // The operands are implicit in the syntax, not absent from the
            // machine: naming them keeps the dependency visible.
            args: vec![reg("hl"), reg("de"), reg("bc")],
        }];
        let (hl_new, de_new, bc_new) = if repeat {
            // After LDIR/LDDR: BC is 0 and the pointers moved by the old BC.
            let adv = |r: &str| {
                if step_up {
                    IrExpr::Add(Box::new(reg(r)), Box::new(reg("bc")))
                } else {
                    IrExpr::Sub(Box::new(reg(r)), Box::new(reg("bc")))
                }
            };
            (adv("hl"), adv("de"), IrExpr::Const(0))
        } else {
            let step = |r: &str| {
                if step_up {
                    IrExpr::Add(Box::new(reg(r)), Box::new(IrExpr::Const(1)))
                } else {
                    IrExpr::Sub(Box::new(reg(r)), Box::new(IrExpr::Const(1)))
                }
            };
            (
                step("hl"),
                step("de"),
                IrExpr::Sub(Box::new(reg("bc")), Box::new(IrExpr::Const(1))),
            )
        };
        if !repeat {
            // The single-step forms move exactly one byte, through the OLD
            // pointers — so the store precedes the increments.
            effects.push(Effect::MemWrite {
                addr: reg("de"),
                value: IrExpr::Deref(Box::new(reg("hl")), 1),
                size: 1,
            });
        }
        effects.push(Effect::RegWrite { reg: "hl".to_string(), value: hl_new });
        effects.push(Effect::RegWrite { reg: "de".to_string(), value: de_new });
        effects.push(Effect::RegWrite { reg: "bc".to_string(), value: bc_new });
        effects
    }

    /// A block instruction whose result is not expressible, but whose CLOBBERS
    /// are: declare them as `Undef` rather than claim nothing happened.
    fn block_clobber(name: &str, regs: &[&str]) -> Vec<Effect> {
        let mut effects = vec![Effect::Intrinsic {
            name: name.to_string(),
            args: vec![IrExpr::Reg("hl".to_string()), IrExpr::Reg("bc".to_string())],
        }];
        for r in regs {
            effects.push(Effect::RegWrite {
                reg: (*r).to_string(),
                value: IrExpr::Undef,
            });
        }
        effects
    }

    /// The accumulator rotates and `DAA`.
    ///
    /// All five named `a` as an intrinsic argument and then wrote NOTHING —
    /// the claim that `RLCA` leaves the accumulator unchanged. These are among
    /// the most common instructions in Z80 code. Same class as the block family:
    /// an intrinsic without effects is an assertion, not opacity.
    ///
    /// `RLCA`/`RRCA` are modelled EXACTLY: the new carry depends only on the old
    /// `A`, and the new `A` only on the old `A`, so writing the flag first and
    /// the accumulator second leaves both reading pre-instruction values.
    ///
    /// `RLA`/`RRA` rotate THROUGH the carry, which makes the two writes mutually
    /// dependent — new `A` needs the old `CF`, new `CF` needs the old `A`. A
    /// sequential effect list cannot express that without a temporary, and fixed
    /// synthetic temp names are the collision trap seen in BPF. So their
    /// CLOBBERS are declared and the rotation stays in the intrinsic.
    fn accumulator_op(name: &str, exact_left: Option<bool>) -> Vec<Effect> {
        let a = || IrExpr::Reg("a".to_string());
        let byte = |e: IrExpr| IrExpr::And(Box::new(e), Box::new(IrExpr::Const(0xFF)));
        let mut effects = vec![Effect::Intrinsic {
            name: name.to_string(),
            args: vec![a()],
        }];
        match exact_left {
            Some(left) => {
                let (carry_bit, rotated) = if left {
                    (
                        // old bit 7
                        IrExpr::And(
                            Box::new(IrExpr::Shr(Box::new(a()), Box::new(IrExpr::Const(7)))),
                            Box::new(IrExpr::Const(1)),
                        ),
                        byte(IrExpr::Or(
                            Box::new(IrExpr::Shl(Box::new(a()), Box::new(IrExpr::Const(1)))),
                            Box::new(IrExpr::Shr(Box::new(a()), Box::new(IrExpr::Const(7)))),
                        )),
                    )
                } else {
                    (
                        // old bit 0
                        IrExpr::And(Box::new(a()), Box::new(IrExpr::Const(1))),
                        byte(IrExpr::Or(
                            Box::new(IrExpr::Shr(Box::new(a()), Box::new(IrExpr::Const(1)))),
                            Box::new(IrExpr::Shl(Box::new(a()), Box::new(IrExpr::Const(7)))),
                        )),
                    )
                };
                // Carry first: it must read the PRE-rotation accumulator.
                effects.push(Effect::RegWrite { reg: "cf".to_string(), value: carry_bit });
                effects.push(Effect::RegWrite { reg: "a".to_string(), value: rotated });
            }
            None => {
                for r in ["a", "cf"] {
                    effects.push(Effect::RegWrite {
                        reg: r.to_string(),
                        value: IrExpr::Undef,
                    });
                }
            }
        }
        effects
    }

    fn mnemonic_to_effects_b(instr: &Instruction) -> Option<Vec<Effect>> {
        let mnem = instr.mnemonic.to_ascii_lowercase();
        // Strip any trailing whitespace the disassembler might emit.
        let _mnem = mnem.trim();

        if let Some(v) = Self::mnemonic_to_effects_b_a(instr) {
            return Some(v);
        }
        Self::mnemonic_to_effects_b_b(instr)
    }
    fn mnemonic_to_effects_c(instr: &Instruction) -> Vec<Effect> {
        let mnem = instr.mnemonic.to_ascii_lowercase();
        // Strip any trailing whitespace the disassembler might emit.
        let mnem = mnem.trim();

            match mnem {
            "ldd" => Self::block_transfer("ldd", false, false),
            "lddr" => Self::block_transfer("lddr", false, true),
            "cpi" => Self::block_clobber("cpi", &["hl","bc"]),
            "cpir" => Self::block_clobber("cpir", &["hl","bc"]),
            "cpd" => Self::block_clobber("cpd", &["hl","bc"]),
            "cpdr" => Self::block_clobber("cpdr", &["hl","bc"]),

            // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Block I/O ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
            "ini" => Self::block_clobber("ini", &["hl","b"]),
            "inir" => Self::block_clobber("inir", &["hl","b"]),
            "ind" => Self::block_clobber("ind", &["hl","b"]),
            "indr" => Self::block_clobber("indr", &["hl","b"]),
            "outi" => Self::block_clobber("outi", &["hl","b"]),
            "otir" => Self::block_clobber("otir", &["hl","b"]),
            "outd" => Self::block_clobber("outd", &["hl","b"]),
            "otdr" => Self::block_clobber("otdr", &["hl","b"]),

            // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ I/O port ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
            "in" => {
                let dst = Self::op_reg_or(instr, 0, "a");
                let port = Self::op_expr(instr, 1);
                vec![Effect::Intrinsic {
                    name: "in".to_string(),
                    args: vec![IrExpr::Reg(dst), port],
                }]
            }
            "out" => {
                let port = Self::op_expr(instr, 0);
                let src = Self::op_expr(instr, 1);
                vec![Effect::Intrinsic {
                    name: "out".to_string(),
                    args: vec![port, src],
                }]
            }

            // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Interrupt control ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
            "di" => vec![Effect::Intrinsic {
                name: "di".to_string(),
                args: vec![],
            }],
            "ei" => vec![Effect::Intrinsic {
                name: "ei".to_string(),
                args: vec![],
            }],
            "im" => {
                let mode = Self::op_expr(instr, 0);
                vec![Effect::Intrinsic {
                    name: "im".to_string(),
                    args: vec![mode],
                }]
            }

            // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Unrecognised ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬
            other => vec![Effect::Intrinsic {
                name: other.to_string(),
                args: instr
                    .operand_list
                    .iter()
                    .map(Self::operand_to_expr)
                    .collect(),
            }],
            }
    }

    fn mnemonic_to_effects(instr: &Instruction) -> Vec<Effect> {
        let mnem = instr.mnemonic.to_ascii_lowercase();
        // Strip any trailing whitespace the disassembler might emit.
        let _ = mnem.trim();

        if let Some(v) = Self::mnemonic_to_effects_a(instr) {
            return v;
        }
        if let Some(v) = Self::mnemonic_to_effects_b(instr) {
            return v;
        }
        Self::mnemonic_to_effects_c(instr)
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ LD dispatcher ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    /// Lift all forms of the Z80 `LD` instruction.
    ///
    /// Recognises (in order of operand structure):
    ///   - LD r, r  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â register to register
    ///   - LD r, n  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â immediate 8-bit to register
    ///   - LD r, (addr) ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â memory read into register (via Memory or Label operand)
    ///   - LD (addr), r ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â memory write from register
    ///   - LD (addr), n ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â memory write from immediate
    ///   - LD rr, nn ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â 16-bit immediate into register pair
    ///   - LD SP, HL  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â copy HL to SP (or IX/IY to SP)
    fn lift_ld_a(instr: &Instruction) -> Vec<Effect> {
        if instr.operand_list.len() < 2 {
            return vec![Effect::Intrinsic {
                name: "ld".to_string(),
                args: vec![Self::op_expr(instr, 0)],
            }];
        }

        let op0 = &instr.operand_list[0];
        let op1 = &instr.operand_list[1];

            match (op0, op1) {
            // LD (nn), A  or  LD (BC/DE), A ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â store A to memory address
            (Operand::Memory { base, disp: 0, .. }, Operand::Register(src_reg)) => {
                let addr_expr = base
                    .as_ref()
                    .map_or(IrExpr::Const(0), |r| IrExpr::Reg(r.name.to_ascii_lowercase()));
                vec![Effect::MemWrite {
                    addr: addr_expr,
                    value: IrExpr::Reg(src_reg.name.to_ascii_lowercase()),
                    size: 1,
                }]
            }
            // LD (IX+d), r  or  LD (IY+d), r ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â store register to indexed memory
            (
                Operand::Memory {
                    base: Some(base_r),
                    disp,
                    ..
                },
                Operand::Register(src_reg),
            ) => {
                let base_expr = IrExpr::Reg(base_r.name.to_ascii_lowercase());
                let disp_expr = IrExpr::Const((*disp).unsigned_abs());
                let addr_expr = if *disp < 0 {
                    IrExpr::Sub(Box::new(base_expr), Box::new(disp_expr))
                } else {
                    IrExpr::Add(Box::new(base_expr), Box::new(disp_expr))
                };
                vec![Effect::MemWrite {
                    addr: addr_expr,
                    value: IrExpr::Reg(src_reg.name.to_ascii_lowercase()),
                    size: 1,
                }]
            }
            // LD (IX+d), n  or  LD (HL), n ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â store immediate to memory
            (Operand::Memory { base, disp, .. }, Operand::Immediate(imm)) => {
                let addr_expr = Self::operand_to_expr(op0);
                let _ = base;
                let _ = disp;
                vec![Effect::MemWrite {
                    addr: addr_expr,
                    value: IrExpr::Const((*imm).cast_unsigned()),
                    size: 1,
                }]
            }
            (Operand::Memory { .. }, Operand::UImmediate(imm)) => {
                let addr_expr = Self::operand_to_expr(op0);
                vec![Effect::MemWrite {
                    addr: addr_expr,
                    value: IrExpr::Const(*imm),
                    size: 1,
                }]
            }
            // LD (nn), rr ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â store 16-bit register pair to absolute memory
            (Operand::Label(addr), Operand::Register(src_reg)) => {
                vec![Effect::MemWrite {
                    addr: IrExpr::Const(*addr),
                    value: IrExpr::Reg(src_reg.name.to_ascii_lowercase()),
                    size: 2,
                }]
            }
                _ => vec![],
            }
    }
    fn lift_ld_b(instr: &Instruction) -> Vec<Effect> {
        if instr.operand_list.len() < 2 {
            return vec![Effect::Intrinsic {
                name: "ld".to_string(),
                args: vec![Self::op_expr(instr, 0)],
            }];
        }

        let op0 = &instr.operand_list[0];
        let op1 = &instr.operand_list[1];

            match (op0, op1) {
            // LD r, (nn) or LD r, (HL) etc. ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â load from memory into register
            (Operand::Register(dst_reg), Operand::Memory { base, disp, .. }) => {
                let base_expr = base
                    .as_ref()
                    .map_or(IrExpr::Const(0), |r| IrExpr::Reg(r.name.to_ascii_lowercase()));
                let addr_expr = if *disp != 0 {
                    let d = IrExpr::Const((*disp).unsigned_abs());
                    if *disp < 0 {
                        IrExpr::Sub(Box::new(base_expr), Box::new(d))
                    } else {
                        IrExpr::Add(Box::new(base_expr), Box::new(d))
                    }
                } else {
                    base_expr
                };
                // Determine load size by destination register width.
                let size = Self::reg_width(&dst_reg.name);
                vec![Effect::MemRead {
                    addr: addr_expr,
                    dest: dst_reg.name.to_ascii_lowercase(),
                    size,
                }]
            }
            // LD rr, (nn) ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â load 16-bit from absolute memory
            (Operand::Register(dst_reg), Operand::Label(addr)) => {
                let size = Self::reg_width(&dst_reg.name);
                vec![Effect::MemRead {
                    addr: IrExpr::Const(*addr),
                    dest: dst_reg.name.to_ascii_lowercase(),
                    size,
                }]
            }
            // LD r, n  or  LD rr, nn ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â load immediate into register
            (Operand::Register(dst_reg), Operand::Immediate(imm)) => {
                vec![Effect::RegWrite {
                    reg: dst_reg.name.to_ascii_lowercase(),
                    value: IrExpr::Const((*imm).cast_unsigned()),
                }]
            }
            (Operand::Register(dst_reg), Operand::UImmediate(imm)) => {
                vec![Effect::RegWrite {
                    reg: dst_reg.name.to_ascii_lowercase(),
                    value: IrExpr::Const(*imm),
                }]
            }
            // LD r, r  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â register to register copy
            (Operand::Register(dst_reg), Operand::Register(src_reg)) => {
                vec![Effect::RegWrite {
                    reg: dst_reg.name.to_ascii_lowercase(),
                    value: IrExpr::Reg(src_reg.name.to_ascii_lowercase()),
                }]
            }
            // Fallback for other forms (LD SP, nn inline etc.)
            _ => {
                let src = Self::op_expr(instr, 1);
                let dst_name = Self::op_reg_or(instr, 0, "a");
                vec![Effect::RegWrite {
                    reg: dst_name,
                    value: src,
                }]
            }
            }
    }

    fn lift_ld(instr: &Instruction) -> Vec<Effect> {
        if instr.operand_list.len() < 2 {
            return vec![Effect::Intrinsic {
                name: "ld".to_string(),
                args: vec![Self::op_expr(instr, 0)],
            }];
        }

        let _ = &instr.operand_list[0];
        let _ = &instr.operand_list[1];

        let __r0 = Self::lift_ld_a(instr);
        if !__r0.is_empty() { return __r0; }
        Self::lift_ld_b(instr)
    }

    /// Return the byte width of a Z80 register by name (lower-case).
    fn reg_width(name: &str) -> u8 {
        match name.to_ascii_lowercase().as_str() {
            "bc" | "de" | "hl" | "sp" | "pc" | "af" | "ix" | "iy" | "bc_shadow" | "de_shadow"
            | "hl_shadow" | "af_shadow" => 2,
            _ => 1,
        }
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ ADD / ADC ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    /// Lift ADD A,r/n/(HL) and ADD HL,rr (16-bit variants).
    fn lift_add(instr: &Instruction) -> Vec<Effect> {
        match instr.operand_list.len() {
            // ADD A, src ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â single-operand or two-operand with A as first
            0 => vec![],
            1 => {
                // ADD src (implicit A destination)
                let src = Self::op_expr(instr, 0);
                vec![Effect::RegWrite {
                    reg: "a".to_string(),
                    value: IrExpr::Add(Box::new(IrExpr::Reg("a".to_string())), Box::new(src)),
                }]
            }
            _ => {
                // Two operands: ADD HL, rr  or  ADD A, src  or  ADD IX, rr
                let dst = Self::op_reg_or(instr, 0, "a");
                let lhs = IrExpr::Reg(dst.clone());
                let rhs = Self::op_expr(instr, 1);
                vec![Effect::RegWrite {
                    reg: dst,
                    value: IrExpr::Add(Box::new(lhs), Box::new(rhs)),
                }]
            }
        }
    }

    /// Lift ADC A,r/n/(HL) and ADC HL,rr (add with carry).
    fn lift_adc(instr: &Instruction) -> Vec<Effect> {
        match instr.operand_list.len() {
            0 => vec![],
            1 => {
                let src = Self::op_expr(instr, 0);
                // A = A + src + CF
                let sum = IrExpr::Add(
                    Box::new(IrExpr::Add(
                        Box::new(IrExpr::Reg("a".to_string())),
                        Box::new(src),
                    )),
                    Box::new(IrExpr::Reg("cf".to_string())),
                );
                vec![Effect::RegWrite {
                    reg: "a".to_string(),
                    value: sum,
                }]
            }
            _ => {
                let dst = Self::op_reg_or(instr, 0, "hl");
                let lhs = IrExpr::Reg(dst.clone());
                let rhs = Self::op_expr(instr, 1);
                let sum = IrExpr::Add(
                    Box::new(IrExpr::Add(Box::new(lhs), Box::new(rhs))),
                    Box::new(IrExpr::Reg("cf".to_string())),
                );
                vec![Effect::RegWrite {
                    reg: dst,
                    value: sum,
                }]
            }
        }
    }

    /// Lift SUB r/n/(HL) (implicit A destination).
    fn lift_sub(instr: &Instruction) -> Vec<Effect> {
        match instr.operand_list.len() {
            0 => vec![],
            1 => {
                let src = Self::op_expr(instr, 0);
                vec![Effect::RegWrite {
                    reg: "a".to_string(),
                    value: IrExpr::Sub(Box::new(IrExpr::Reg("a".to_string())), Box::new(src)),
                }]
            }
            _ => {
                // Some assemblers emit SUB A, src
                let dst = Self::op_reg_or(instr, 0, "a");
                let lhs = IrExpr::Reg(dst.clone());
                let rhs = Self::op_expr(instr, 1);
                vec![Effect::RegWrite {
                    reg: dst,
                    value: IrExpr::Sub(Box::new(lhs), Box::new(rhs)),
                }]
            }
        }
    }

    /// Lift SBC A,r/n/(HL) and SBC HL,rr (subtract with carry).
    fn lift_sbc(instr: &Instruction) -> Vec<Effect> {
        match instr.operand_list.len() {
            0 => vec![],
            1 => {
                let src = Self::op_expr(instr, 0);
                let diff = IrExpr::Sub(
                    Box::new(IrExpr::Sub(
                        Box::new(IrExpr::Reg("a".to_string())),
                        Box::new(src),
                    )),
                    Box::new(IrExpr::Reg("cf".to_string())),
                );
                vec![Effect::RegWrite {
                    reg: "a".to_string(),
                    value: diff,
                }]
            }
            _ => {
                let dst = Self::op_reg_or(instr, 0, "hl");
                let lhs = IrExpr::Reg(dst.clone());
                let rhs = Self::op_expr(instr, 1);
                let diff = IrExpr::Sub(
                    Box::new(IrExpr::Sub(Box::new(lhs), Box::new(rhs))),
                    Box::new(IrExpr::Reg("cf".to_string())),
                );
                vec![Effect::RegWrite {
                    reg: dst,
                    value: diff,
                }]
            }
        }
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ INC / DEC ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    fn lift_inc(instr: &Instruction) -> Vec<Effect> {
        match instr.operand_list.first() {
            Some(Operand::Register(r)) => {
                let name = r.name.to_ascii_lowercase();
                let src = IrExpr::Reg(name.clone());
                vec![Effect::RegWrite {
                    reg: name,
                    value: IrExpr::Add(Box::new(src), Box::new(IrExpr::Const(1))),
                }]
            }
            Some(op @ Operand::Memory { .. }) => {
                // INC (HL) / INC (IX+d): read-modify-write
                let addr = Self::operand_to_expr(op);
                // We model this as an intrinsic because we cannot express
                // read-modify-write on memory without a temporary register.
                vec![Effect::Intrinsic {
                    name: "inc_mem".to_string(),
                    args: vec![addr],
                }]
            }
            _ => vec![Effect::Intrinsic {
                name: "inc".to_string(),
                args: instr
                    .operand_list
                    .iter()
                    .map(Self::operand_to_expr)
                    .collect(),
            }],
        }
    }

    fn lift_dec(instr: &Instruction) -> Vec<Effect> {
        match instr.operand_list.first() {
            Some(Operand::Register(r)) => {
                let name = r.name.to_ascii_lowercase();
                let src = IrExpr::Reg(name.clone());
                vec![Effect::RegWrite {
                    reg: name,
                    value: IrExpr::Sub(Box::new(src), Box::new(IrExpr::Const(1))),
                }]
            }
            Some(Operand::Memory { .. }) => {
                let addr = Self::operand_to_expr(instr.operand_list.first().unwrap());
                vec![Effect::Intrinsic {
                    name: "dec_mem".to_string(),
                    args: vec![addr],
                }]
            }
            _ => vec![Effect::Intrinsic {
                name: "dec".to_string(),
                args: instr
                    .operand_list
                    .iter()
                    .map(Self::operand_to_expr)
                    .collect(),
            }],
        }
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Bitwise logic (AND / OR / XOR) ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    /// Lift an 8-bit logic instruction that operates on A (and an optional src).
    fn lift_bitop<F>(instr: &Instruction, op: F) -> Vec<Effect>
    where
        F: Fn(Box<IrExpr>, Box<IrExpr>) -> IrExpr,
    {
        let src = match instr.operand_list.len() {
            0 => return vec![],
            1 => Self::op_expr(instr, 0),
            _ => Self::op_expr(instr, 1),
        };
        vec![Effect::RegWrite {
            reg: "a".to_string(),
            value: op(Box::new(IrExpr::Reg("a".to_string())), Box::new(src)),
        }]
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Shift / Rotate ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    fn lift_shift_rotate(instr: &Instruction, op_name: &str) -> Vec<Effect> {
        match instr.operand_list.first() {
            Some(Operand::Register(r)) => {
                let name = r.name.to_ascii_lowercase();
                let src = IrExpr::Reg(name.clone());
                let result = match op_name {
                    "sla" => IrExpr::Shl(Box::new(src), Box::new(IrExpr::Const(1))),
                    "srl" => IrExpr::Shr(Box::new(src), Box::new(IrExpr::Const(1))),
                    "sra" => {
                        return vec![Effect::Intrinsic {
                            name: "sra".to_string(),
                            args: vec![IrExpr::Reg(name)],
                        }];
                    }
                    _ => {
                        // RLC, RRC, RL, RR ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â modelled as intrinsics (they involve CF)
                        return vec![Effect::Intrinsic {
                            name: op_name.to_string(),
                            args: vec![IrExpr::Reg(name)],
                        }];
                    }
                };
                vec![Effect::RegWrite {
                    reg: name,
                    value: result,
                }]
            }
            Some(Operand::Memory { .. }) => {
                let addr = Self::operand_to_expr(instr.operand_list.first().unwrap());
                vec![Effect::Intrinsic {
                    name: op_name.to_string(),
                    args: vec![addr],
                }]
            }
            _ => vec![Effect::Intrinsic {
                name: op_name.to_string(),
                args: instr
                    .operand_list
                    .iter()
                    .map(Self::operand_to_expr)
                    .collect(),
            }],
        }
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ JP / JR / CALL / RET ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    /// Lift JP ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â unconditional or conditional absolute jump.
    ///
    /// Forms:
    ///   - JP nn          ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â unconditional (1 operand)
    ///   - JP (HL/IX/IY)  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â indirect unconditional (1 operand, Memory)
    ///   - JP cc, nn      ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â conditional (2 operands)
    fn lift_jp(instr: &Instruction) -> Vec<Effect> {
        match instr.operand_list.len() {
            0 => vec![],
            1 => {
                // Unconditional: JP nn  or  JP (HL)
                let target = Self::branch_target(instr);
                vec![Effect::Branch {
                    target,
                    condition: None,
                }]
            }
            _ => {
                // Conditional: JP cc, nn
                let cond = Self::cond_from_op0(instr);
                let target = Self::cond_branch_target(instr);
                vec![Effect::Branch {
                    target,
                    condition: cond,
                }]
            }
        }
    }

    /// Lift JR ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â unconditional or conditional relative jump.
    ///
    /// Forms:
    ///   - JR e        ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â unconditional (1 operand: signed offset)
    ///   - JR cc, e    ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â conditional (2 operands)
    fn lift_jr(instr: &Instruction) -> Vec<Effect> {
        match instr.operand_list.len() {
            0 => vec![],
            1 => {
                let target = Self::branch_target(instr);
                vec![Effect::Branch {
                    target,
                    condition: None,
                }]
            }
            _ => {
                let cond = Self::cond_from_op0(instr);
                // For JR cc, e the offset is operand 1.
                let next_pc = instr.address.0.wrapping_add(instr.size as u64);
                let target = match instr.operand_list.get(1) {
                    Some(Operand::Immediate(off)) => {
                        IrExpr::Const(next_pc.wrapping_add((*off).cast_unsigned()))
                    }
                    Some(Operand::Label(addr)) => IrExpr::Const(*addr),
                    _ => IrExpr::Const(next_pc),
                };
                vec![Effect::Branch {
                    target,
                    condition: cond,
                }]
            }
        }
    }

    /// Lift CALL ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â unconditional or conditional subroutine call.
    ///
    /// Forms:
    ///   - CALL nn      ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â unconditional
    ///   - CALL cc, nn  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â conditional
    fn lift_call(instr: &Instruction) -> Vec<Effect> {
        match instr.operand_list.len() {
            0 => vec![],
            1 => {
                let target = Self::branch_target(instr);
                // Push return address onto stack, then call.
                let sp = IrExpr::Reg("sp".to_string());
                let new_sp = IrExpr::Sub(Box::new(sp), Box::new(IrExpr::Const(2)));
                let ret_addr = instr.address.0.wrapping_add(instr.size as u64);
                vec![
                    Effect::RegWrite {
                        reg: "sp".to_string(),
                        value: new_sp.clone(),
                    },
                    Effect::MemWrite {
                        addr: new_sp,
                        value: IrExpr::Const(ret_addr),
                        size: 2,
                    },
                    Effect::Call { target },
                ]
            }
            _ => {
                // Conditional CALL cc, nn
                let cond = Self::cond_from_op0(instr);
                let target = Self::cond_branch_target(instr);
                let sp = IrExpr::Reg("sp".to_string());
                let new_sp = IrExpr::Sub(Box::new(sp), Box::new(IrExpr::Const(2)));
                let ret_addr = instr.address.0.wrapping_add(instr.size as u64);
                // For conditional CALL we model the stack push as unconditional
                // (conservative over-approximation) and add the condition on
                // the Call effect ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â the stack effects only matter when the call
                // is taken, so this is a slight over-approximation.  A full
                // implementation would need phi-nodes to model both paths.
                if cond.is_some() {
                    // Conditional call: emit as conditional branch + intrinsic
                    vec![
                        Effect::Intrinsic {
                            name: "call_cond_setup".to_string(),
                            args: vec![IrExpr::Const(ret_addr)],
                        },
                        Effect::Branch {
                            target,
                            condition: cond,
                        },
                    ]
                } else {
                    vec![
                        Effect::RegWrite {
                            reg: "sp".to_string(),
                            value: new_sp.clone(),
                        },
                        Effect::MemWrite {
                            addr: new_sp,
                            value: IrExpr::Const(ret_addr),
                            size: 2,
                        },
                        Effect::Call { target },
                    ]
                }
            }
        }
    }

    /// Lift RET ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â unconditional or conditional return.
    fn lift_ret(instr: &Instruction) -> Vec<Effect> {
        if instr.operand_list.is_empty() {
            // Unconditional RET: PC = [SP]; SP += 2
            let sp = IrExpr::Reg("sp".to_string());
            vec![
                Effect::MemRead {
                    addr: sp.clone(),
                    dest: "pc".to_string(),
                    size: 2,
                },
                Effect::RegWrite {
                    reg: "sp".to_string(),
                    value: IrExpr::Add(Box::new(sp), Box::new(IrExpr::Const(2))),
                },
                Effect::Return { value: None },
            ]
        } else {
            // Conditional RET cc
            let cond = Self::cond_from_op0(instr);
            vec![Effect::Branch {
                target: IrExpr::Deref(Box::new(IrExpr::Reg("sp".to_string())), 2),
                condition: cond,
            }]
        }
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ EX ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    /// Lift EX in all its forms:
    ///   - EX AF, AF'       ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â swap AF with shadow
    ///   - EX DE, HL        ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â swap DE and HL
    ///   - EX (SP), HL      ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â swap top-of-stack with HL
    ///   - EX (SP), IX      ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â swap top-of-stack with IX
    fn lift_ex(instr: &Instruction) -> Vec<Effect> {
        match (instr.operand_list.first(), instr.operand_list.get(1)) {
            // EX AF, AF' ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â use intrinsic (shadow swap)
            (Some(Operand::Register(r0)), Some(Operand::Register(r1)))
                if r0.name.eq_ignore_ascii_case("af")
                    && r1.name.to_ascii_lowercase().starts_with("af") =>
            {
                vec![Effect::Intrinsic {
                    name: "ex_af".to_string(),
                    args: vec![],
                }]
            }
            // EX DE, HL ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â swap DE and HL via temps
            (Some(Operand::Register(r0)), Some(Operand::Register(r1))) => {
                let a = r0.name.to_ascii_lowercase();
                let b = r1.name.to_ascii_lowercase();
                vec![
                    // tmp = a; a = b; b = tmp  (modelled as two concurrent writes
                    // since IR has no temp; the second read sees the original value)
                    Effect::RegWrite {
                        reg: a.clone(),
                        value: IrExpr::Reg(b.clone()),
                    },
                    Effect::RegWrite {
                        reg: b,
                        value: IrExpr::Reg(a),
                    },
                ]
            }
            // EX (SP), HL / IX / IY ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â swap top-of-stack with register
            (Some(Operand::Memory { .. }), Some(Operand::Register(r1))) => {
                let rr = r1.name.to_ascii_lowercase();
                vec![
                    // tmp = [SP]; [SP] = rr; rr = tmp  (use intrinsic for atomicity)
                    Effect::Intrinsic {
                        name: "ex_sp".to_string(),
                        args: vec![IrExpr::Reg(rr)],
                    },
                ]
            }
            _ => vec![Effect::Intrinsic {
                name: "ex".to_string(),
                args: instr
                    .operand_list
                    .iter()
                    .map(Self::operand_to_expr)
                    .collect(),
            }],
        }
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ IR text formatter ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    /// Produce a human-readable IR text string from a list of effects.
    fn effects_to_ir_text(effects: &[Effect]) -> String {
        if effects.is_empty() {
            "nop".to_string()
        } else {
            effects
                .iter()
                .map(std::string::ToString::to_string)
                .collect::<Vec<_>>()
                .join("; ")
        }
    }
}

