impl ArchLifter for Z80Lifter {
    fn arch_name(&self) -> &'static str {
        "z80"
    }

    fn lift_level(&self) -> LiftLevel {
        LiftLevel::Llil
    }

    fn description(&self) -> &'static str {
        "Z80 LLIL lifter ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â full ISA (8-bit, 16-bit pairs, IX/IY, CB/ED prefix ops)"
    }

    fn lift(&self, instr: &Instruction) -> Result<LiftedInstr, LiftError> {
        let effects = Self::mnemonic_to_effects(instr);
        let ir_text = Self::effects_to_ir_text(&effects);
        Ok(LiftedInstr {
            address: instr.address.0,
            original_mnemonic: instr.mnemonic.clone(),
            ir_text,
            il_level: LiftLevel::Llil,
            effects,
        })
    }

    fn supports_mnemonic(&self, mnemonic: &str) -> bool {
        // Z80 mnemonics are short and well-known; we support everything via the
        // intrinsic fallback, so always return true.
        let _ = mnemonic;
        true
    }
}

