    fn test_lift_level() {
        let l = Z80Lifter::new();
        assert_eq!(l.lift_level(), LiftLevel::Llil);
    }

    #[test]
    fn test_description_nonempty() {
        let l = Z80Lifter::new();
        assert!(!l.description().is_empty());
    }

