    #[test]
    fn test_nop_has_no_effects() {
        let l = Z80Lifter::new();
        let instr = make_instr(0x0000, "nop");
        let li = l.lift(&instr).unwrap();
        assert!(li.effects.is_empty(), "NOP must produce no effects");
        assert_eq!(li.ir_text, "nop");
        assert_eq!(li.address, 0x0000);
        assert_eq!(li.il_level, LiftLevel::Llil);
    }

