    #[test]
    fn test_ld_reg_to_reg() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x0100, "ld");
        instr.operand_list = vec![reg8("A"), reg8("B")];
        let li = l.lift(&instr).unwrap();
        assert_eq!(li.effects.len(), 1);
        match &li.effects[0] {
            Effect::RegWrite { reg, value } => {
                assert_eq!(reg, "a");
                assert_eq!(value, &IrExpr::Reg("b".to_string()));
            }
            other => panic!("expected RegWrite, got {other:?}"),
        }
    }

    #[test]
    fn test_ld_reg_to_reg_lowercase() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x0100, "ld");
        instr.operand_list = vec![reg8("H"), reg8("L")];
        let li = l.lift(&instr).unwrap();
        if let Effect::RegWrite { reg, value } = &li.effects[0] {
            assert_eq!(reg, "h");
            assert_eq!(value, &IrExpr::Reg("l".to_string()));
        } else {
            panic!("expected RegWrite");
        }
    }

