    #[test]
    fn test_ld_ix_disp_reg() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x0600, "ld");
        instr.operand_list = vec![mem_reg_disp("IX", 4), reg8("A")];
        let li = l.lift(&instr).unwrap();
        assert_eq!(li.effects.len(), 1);
        match &li.effects[0] {
            Effect::MemWrite { addr, value, .. } => {
                // addr must be IX + 4
                assert!(matches!(addr, IrExpr::Add(_, _)));
                assert_eq!(value, &IrExpr::Reg("a".to_string()));
            }
            other => panic!("expected MemWrite, got {other:?}"),
        }
    }

