    #[test]
    fn test_add_a_imm() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x0900, "add");
        instr.operand_list = vec![reg8("A"), imm8(10)];
        let li = l.lift(&instr).unwrap();
        match &li.effects[0] {
            Effect::RegWrite { reg, value } => {
                assert_eq!(reg, "a");
                if let IrExpr::Add(lhs, rhs) = value {
                    assert_eq!(**lhs, IrExpr::Reg("a".to_string()));
                    assert_eq!(**rhs, IrExpr::Const(10));
                } else {
                    panic!("expected Add expression");
                }
            }
            other => panic!("expected RegWrite, got {other:?}"),
        }
    }

