    #[test]
    fn test_inc_reg8() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x0f00, "inc");
        instr.operand_list = vec![reg8("B")];
        let li = l.lift(&instr).unwrap();
        match &li.effects[0] {
            Effect::RegWrite { reg, value } => {
                assert_eq!(reg, "b");
                if let IrExpr::Add(_, rhs) = value {
                    assert_eq!(**rhs, IrExpr::Const(1));
                } else {
                    panic!("expected Add(b, 1)");
                }
            }
            other => panic!("expected RegWrite, got {other:?}"),
        }
    }

