    #[test]
    fn test_cp_reg() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x1300, "cp");
        instr.operand_list = vec![reg8("D")];
        let li = l.lift(&instr).unwrap();
        match &li.effects[0] {
            Effect::Intrinsic { name, args } => {
                assert_eq!(name, "cp");
                assert_eq!(args.len(), 2);
                assert_eq!(args[0], IrExpr::Reg("a".to_string()));
                assert_eq!(args[1], IrExpr::Reg("d".to_string()));
            }
            other => panic!("expected Intrinsic(cp), got {other:?}"),
        }
    }

