    #[test]
    fn test_jp_unconditional() {
        let l = Z80Lifter::new();
        let mut instr = make_instr_sz(0x1400, 3, "jp");
        instr.operand_list = vec![label(0x2000)];
        let li = l.lift(&instr).unwrap();
        assert!(li.is_terminator());
        match &li.effects[0] {
            Effect::Branch { target, condition } => {
                assert_eq!(target, &IrExpr::Const(0x2000));
                assert!(
                    condition.is_none(),
                    "unconditional JP must have no condition"
                );
            }
            other => panic!("expected Branch, got {other:?}"),
        }
    }

