    #[test]
    fn test_jp_indirect_hl() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x1500, "jp");
        instr.operand_list = vec![mem_reg("HL")];
        let li = l.lift(&instr).unwrap();
        match &li.effects[0] {
            Effect::Branch { target, condition } => {
                // target is the value of HL (the effective address of the mem operand)
                assert_eq!(target, &IrExpr::Reg("hl".to_string()));
                assert!(condition.is_none());
            }
            other => panic!("expected Branch, got {other:?}"),
        }
    }

