    #[test]
    fn test_jp_conditional_z() {
        let l = Z80Lifter::new();
        let mut instr = make_instr_sz(0x1600, 3, "jp");
        // JP Z, 0x3000
        instr.operand_list = vec![condition_reg("Z"), label(0x3000)];
        let li = l.lift(&instr).unwrap();
        match &li.effects[0] {
            Effect::Branch { target, condition } => {
                assert_eq!(target, &IrExpr::Const(0x3000));
                // Condition must be Some (Z flag set = not zero)
                assert!(condition.is_some(), "conditional JP must carry a condition");
            }
            other => panic!("expected Branch, got {other:?}"),
        }
    }

    #[test]
    fn test_jp_conditional_nc() {
        let l = Z80Lifter::new();
        let mut instr = make_instr_sz(0x1700, 3, "jp");
        instr.operand_list = vec![condition_reg("NC"), label(0x4000)];
        let li = l.lift(&instr).unwrap();
        match &li.effects[0] {
            Effect::Branch { condition, .. } => {
                assert!(condition.is_some());
                // NC = CF == 0 => CmpEqZero(cf)
                assert!(matches!(condition.as_ref().unwrap(), IrExpr::CmpEqZero(_)));
            }
            other => panic!("expected Branch, got {other:?}"),
        }
    }

