    #[test]
    fn test_jr_unconditional() {
        let l = Z80Lifter::new();
        // JR +5: next_pc = 0x2000 + 2; target = 0x2002 + 5 = 0x2007
        let mut instr = make_instr_sz(0x2000, 2, "jr");
        instr.operand_list = vec![imm8(5)];
        let li = l.lift(&instr).unwrap();
        assert!(li.is_terminator());
        match &li.effects[0] {
            Effect::Branch { target, condition } => {
                // next_pc = 0x2002; offset = 5 ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢ target = 0x2007
                assert_eq!(target, &IrExpr::Const(0x2007));
                assert!(condition.is_none());
            }
            other => panic!("expected Branch, got {other:?}"),
        }
    }

    #[test]
    fn test_jr_nz() {
        let l = Z80Lifter::new();
        let mut instr = make_instr_sz(0x2010, 2, "jr");
        instr.operand_list = vec![condition_reg("NZ"), imm8(-2_i64)];
        let li = l.lift(&instr).unwrap();
        match &li.effects[0] {
            Effect::Branch { condition, .. } => {
                // NZ = CmpEqZero(zf) (i.e. zf == 0)
                assert!(condition.is_some());
                assert!(matches!(condition.as_ref().unwrap(), IrExpr::CmpEqZero(_)));
            }
            other => panic!("expected Branch, got {other:?}"),
        }
    }

    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ CALL unconditional ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    #[test]
    fn test_call_unconditional() {
        let l = Z80Lifter::new();
        let mut instr = make_instr_sz(0x3000, 3, "call");
        instr.operand_list = vec![label(0x5000)];
        let li = l.lift(&instr).unwrap();
        // Must contain: SP write, mem write, Call
        let has_sp_write = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::RegWrite { reg, .. } if reg == "sp"));
        let has_mem_write = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::MemWrite { .. }));
        let has_call = li.effects.iter().any(|e| matches!(e, Effect::Call { .. }));
        assert!(has_sp_write, "CALL must decrement SP");
        assert!(has_mem_write, "CALL must push return address");
        assert!(has_call, "CALL must emit Call effect");

        // Verify target
        let call_eff = li
            .effects
            .iter()
            .find(|e| matches!(e, Effect::Call { .. }))
            .unwrap();
        if let Effect::Call { target } = call_eff {
            assert_eq!(target, &IrExpr::Const(0x5000));
        }
    }

