    #[test]
    fn test_ret_conditional_c() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x4100, "ret");
        instr.operand_list = vec![condition_reg("C")];
        let li = l.lift(&instr).unwrap();
        let branch = li
            .effects
            .iter()
            .find(|e| matches!(e, Effect::Branch { .. }));
        assert!(branch.is_some(), "conditional RET must emit a Branch");
        if let Some(Effect::Branch { condition, .. }) = branch {
            assert!(
                condition.is_some(),
                "conditional RET must carry a condition"
            );
        }
    }

