    #[test]
    fn test_push_bc() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x5000, "push");
        instr.operand_list = vec![reg16("BC")];
        let li = l.lift(&instr).unwrap();
        // Expect: SP = SP - 2; [SP] = BC
        let sp_dec = li.effects.iter().any(|e| {
            matches!(e, Effect::RegWrite { reg, value }
                if reg == "sp" && matches!(value, IrExpr::Sub(_, _)))
        });
        let mem_write = li.effects.iter().any(|e| {
            matches!(e, Effect::MemWrite { value, size: 2, .. }
                if value == &IrExpr::Reg("bc".to_string()))
        });
        assert!(sp_dec, "PUSH must decrement SP");
        assert!(mem_write, "PUSH must write register to [SP]");
    }

    #[test]
    fn test_pop_hl() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x5100, "pop");
        instr.operand_list = vec![reg16("HL")];
        let li = l.lift(&instr).unwrap();
        let mem_read = li
            .effects
            .iter()
            .any(|e| matches!(e, Effect::MemRead { dest, size: 2, .. } if dest == "hl"));
        let sp_inc = li.effects.iter().any(|e| {
            matches!(e, Effect::RegWrite { reg, value }
                if reg == "sp" && matches!(value, IrExpr::Add(_, _)))
        });
        assert!(mem_read, "POP must load from [SP] into HL");
        assert!(sp_inc, "POP must increment SP");
    }

