    #[test]
    fn test_djnz() {
        let l = Z80Lifter::new();
        let mut instr = make_instr_sz(0x6000, 2, "djnz");
        instr.operand_list = vec![imm8(-4_i64)];
        let li = l.lift(&instr).unwrap();
        // Must contain: RegWrite B = B - 1, Branch (conditional)
        let b_dec = li.effects.iter().any(|e| {
            matches!(e, Effect::RegWrite { reg, value }
                if reg == "b" && matches!(value, IrExpr::Sub(_, _)))
        });
        let branch = li.effects.iter().any(|e| {
            matches!(
                e,
                Effect::Branch {
                    condition: Some(_),
                    ..
                }
            )
        });
        assert!(b_dec, "DJNZ must decrement B");
        assert!(branch, "DJNZ must conditionally branch");
    }

