    #[test]
    fn test_rst_38h() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x7000, "rst");
        instr.operand_list = vec![imm8(0x38)];
        let li = l.lift(&instr).unwrap();
        let has_call = li.effects.iter().any(|e| matches!(e, Effect::Call { .. }));
        assert!(has_call, "RST must emit a Call effect");
        if let Some(Effect::Call { target }) =
            li.effects.iter().find(|e| matches!(e, Effect::Call { .. }))
        {
            assert_eq!(target, &IrExpr::Const(0x38));
        }
    }

