    fn test_ex_de_hl() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0xa000, "ex");
        instr.operand_list = vec![reg16("DE"), reg16("HL")];
        let li = l.lift(&instr).unwrap();
        assert_eq!(li.effects.len(), 2);
        let de_write = li.effects.iter().any(|e| {
            matches!(e, Effect::RegWrite { reg, value }
                if reg == "de" && value == &IrExpr::Reg("hl".to_string()))
        });
        let hl_write = li.effects.iter().any(|e| {
            matches!(e, Effect::RegWrite { reg, value }
                if reg == "hl" && value == &IrExpr::Reg("de".to_string()))
        });
        assert!(de_write, "EX DE, HL must write HL to DE");
        assert!(hl_write, "EX DE, HL must write DE to HL");
    }

