    // ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ Block ops ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬ÃƒÂ¢Ã¢â‚¬ÂÃ¢â€šÂ¬

    /// The Z80 BLOCK instructions take no operands in the syntax, and every one
    /// of them lifted to a bare intrinsic with `args: vec![]` and NO register
    /// writes. That is not opacity — it is the claim that `LDIR` leaves HL, DE
    /// and BC untouched, which a liveness or dead-store pass will believe.
    /// Same class as the arch-x86 register-effect sweep.
    ///
    /// `LDI`/`LDD` are exact; the repeating forms end with `BC = 0` and the
    /// pointers advanced by the ORIGINAL count, which is also exact. The block
    /// copy itself stays an intrinsic — a loop is not expressible here.
    /// `RLCA`/`RLA`/`RRCA`/`RRA`/`DAA` named `a` as an intrinsic argument and
    /// then wrote NOTHING — the claim that the accumulator is unchanged, for
    /// five of the most common instructions in Z80 code.
    ///
    /// `RLCA`/`RRCA` are exact. `RLA`/`RRA` rotate THROUGH the carry, making
    /// the two writes mutually dependent, which a sequential effect list cannot
    /// express without a temporary — so their clobbers are declared instead.
    /// `DAA`'s BCD adjust depends on several flags and is left opaque.
    #[test]
    fn accumulator_ops_write_the_accumulator() {
        let l = Z80Lifter::new();
        let render = |m: &str| format!("{:?}", l.lift(&make_instr(0x100, m)).unwrap().effects);

        for m in ["rlca", "rrca", "rla", "rra", "daa"] {
            let t = render(m);
            assert!(
                t.contains("reg: \"a\""),
                "{m} modifies the accumulator and must say so: {t}"
            );
            assert!(t.contains("reg: \"cf\""), "{m} affects carry: {t}");
        }

        // The circular-free pair is modelled exactly, and the two directions
        // must not collapse into one expression.
        let rlca = render("rlca");
        assert!(!rlca.contains("Undef"), "rlca is exactly expressible: {rlca}");
        assert!(rlca.contains("Const(7)"), "rlca wraps bit 7 round: {rlca}");
        // Compare only the WRITES: the intrinsic names differ by construction,
        // so comparing the whole rendering would pass even if both rotated the
        // same way. That is the self-neutralising assertion this file keeps
        // finding elsewhere — the first version of this test had it.
        let writes = |m: &str| {
            l.lift(&make_instr(0x100, m))
                .unwrap()
                .effects
                .iter()
                .filter(|e| matches!(e, Effect::RegWrite { .. }))
                .map(|e| format!("{e:?}"))
                .collect::<Vec<_>>()
        };
        assert_ne!(
            writes("rlca"),
            writes("rrca"),
            "rlca and rrca must not rotate the same way"
        );

        // Rotate-through-carry stays declared-but-opaque, on purpose.
        assert!(
            render("rla").contains("Undef"),
            "rla needs a temporary to be exact; its clobbers are declared instead"
        );
    }

    #[test]
    fn block_instructions_declare_their_register_effects() {
        let l = Z80Lifter::new();
        let render = |m: &str| format!("{:?}", l.lift(&make_instr(0xe000, m)).unwrap().effects);

        for m in ["ldi", "ldir", "ldd", "lddr", "cpi", "cpir", "ini", "outi", "exx"] {
            let t = render(m);
            for r in ["hl"] {
                assert!(
                    t.contains(&format!("reg: \"{r}\"")),
                    "{m} modifies {r} and must say so: {t}"
                );
            }
        }

        // LDI steps by one and moves a byte through the OLD pointers.
        let ldi = render("ldi");
        assert!(ldi.contains("MemWrite"), "ldi moves a byte: {ldi}");
        assert!(ldi.contains("Const(1)"), "ldi steps by one: {ldi}");

        // LDIR ends with BC == 0 and the pointers advanced by the old BC.
        let ldir = render("ldir");
        assert!(
            ldir.contains("reg: \"bc\", value: Const(0)"),
            "ldir runs BC down to zero: {ldir}"
        );
        assert!(
            ldir.contains("Add(Reg(\"hl\"), Reg(\"bc\"))"),
            "ldir advances HL by the original count: {ldir}"
        );

        // LDD walks backwards.
        let ldd = render("ldd");
        assert!(ldd.contains("Sub"), "ldd decrements: {ldd}");
        assert_ne!(render("ldi"), ldd, "ldi and ldd must not lift identically");
    }

