    #[test]
    fn test_adc_a_reg() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x1a00, "adc");
        instr.operand_list = vec![reg8("A"), reg8("H")];
        let li = l.lift(&instr).unwrap();
        match &li.effects[0] {
            Effect::RegWrite { reg, value } => {
                assert_eq!(reg, "a");
                // A + H + CF
                assert!(matches!(value, IrExpr::Add(_, _)));
            }
            other => panic!("expected RegWrite, got {other:?}"),
        }
    }

