    #[test]
    fn test_ld_absolute_mem_reg16() {
        let l = Z80Lifter::new();
        let mut instr = make_instr(0x1c00, "ld");
        // LD (0xC000), HL
        instr.operand_list = vec![label(0xC000), reg16("HL")];
        let li = l.lift(&instr).unwrap();
        match &li.effects[0] {
            Effect::MemWrite { addr, value, .. } => {
                assert_eq!(addr, &IrExpr::Const(0xC000));
                assert_eq!(value, &IrExpr::Reg("hl".to_string()));
            }
            other => panic!("expected MemWrite, got {other:?}"),
        }
    }

